// Toont of het weerstation online is (retained bericht + Last Will van de generator).
const online = msg.payload === "online";
const tijd = new Date().toLocaleTimeString("nl-BE");
node.status({ fill: online ? "green" : "red", shape: online ? "dot" : "ring",
              text: `station ${msg.payload} (sinds ${tijd})` });
flow.set("station_online", online);
return msg;

// Valideert elke weermeting.
// Uitgang 1: geldige meting  -> verdere verwerking
// Uitgang 2: afgewezen meting met reden -> weer/fouten + InfluxDB
const REGELS = {
    "weer/temperatuur":      { waarde:     { min: -50, max: 60,  sprong: 3 } },
    "weer/luchtvochtigheid": { waarde:     { min: 0,   max: 100, sprong: 15 } },
    "weer/wind":             { snelheid:   { min: 0,   max: 200, sprong: 45 },
                               richting:   { min: 0,   max: 360 } },
    "weer/regen":            { mm_per_uur: { min: 0,   max: 500, sprong: 8 } }
};
const SPRONG_MAX_LEEFTIJD_MS = 60000; // vorige waarde ouder dan 60 s: geen sprongcontrole
const SPRONG_ACCEPTEER_NA = 3;        // 3 sprongen op rij = echte verandering, dan aanvaarden

const regels = REGELS[msg.topic];
if (!regels) return null; // onbekend topic: negeren

const stats = context.get("stats") || { ok: 0, fout: 0 };

function toonStatus() {
    const totaal = stats.ok + stats.fout;
    const pct = totaal ? (100 * stats.fout / totaal).toFixed(1) : "0.0";
    node.status({ fill: stats.fout ? "yellow" : "green", shape: "dot",
                  text: `ok ${stats.ok} | fout ${stats.fout} (${pct}%)` });
}

function afwijzen(reden, veld, waarde, extra) {
    stats.fout++;
    context.set("stats", stats);
    toonStatus();
    const d = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
    return [null, {
        topic: "weer/fouten",
        payload: {
            bron_topic: msg.topic,
            station: d.station || "onbekend",
            reden: reden,
            veld: veld,
            waarde: waarde === undefined ? null : waarde,
            ...extra,
            origineel: msg.payload,
            ts: d.ts || new Date().toISOString()
        }
    }];
}

const data = msg.payload;
if (!data || typeof data !== "object" || Array.isArray(data)) {
    return afwijzen("geen JSON-object", null, data);
}
if (!data.station) return afwijzen("ontbrekend veld", "station");
if (!data.ts) return afwijzen("ontbrekend veld", "ts");
if (isNaN(Date.parse(data.ts))) return afwijzen("ongeldige tijd", "ts", data.ts);

// 1) Bestaat elk veld, is het een getal en ligt het binnen het bereik?
for (const [veld, r] of Object.entries(regels)) {
    const w = data[veld];
    if (!(veld in data)) return afwijzen("ontbrekend veld", veld);
    if (typeof w !== "number" || !Number.isFinite(w)) return afwijzen("verkeerd type", veld, w);
    if (w < r.min || w > r.max) return afwijzen("buiten bereik", veld, w, { min: r.min, max: r.max });
}

// 2) Spike-filter: wijkt de waarde onrealistisch veel af van de mediaan van de laatste
//    5 geldige metingen? (mediaan i.p.v. vorige waarde: een losse windstoot verstoort hem niet)
const vorige = context.get("vorige") || {};
const nu = Date.now();
function mediaan(lijst) {
    const s = [...lijst].sort((a, b) => a - b);
    const m = Math.floor(s.length / 2);
    return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
}
for (const [veld, r] of Object.entries(regels)) {
    if (!r.sprong) continue;
    const v = vorige[msg.topic + "." + veld];
    if (!v || nu - v.tijd > SPRONG_MAX_LEEFTIJD_MS) continue;
    const ref = Math.round(mediaan(v.waarden) * 10) / 10;
    if (Math.abs(data[veld] - ref) > r.sprong) {
        v.sprongen = (v.sprongen || 0) + 1;
        if (v.sprongen < SPRONG_ACCEPTEER_NA) {
            context.set("vorige", vorige);
            return afwijzen("sprong", veld, data[veld], { referentie: ref, max_verschil: r.sprong });
        }
        v.waarden = []; // echte, blijvende verandering: referentie opnieuw opbouwen
    }
}

// Geldig: onthoud deze waarden (max. 5) als referentie voor de volgende metingen.
for (const veld of Object.keys(regels)) {
    const sleutel = msg.topic + "." + veld;
    const v = vorige[sleutel] && nu - vorige[sleutel].tijd <= SPRONG_MAX_LEEFTIJD_MS
        ? vorige[sleutel] : { waarden: [] };
    v.waarden = [...v.waarden, data[veld]].slice(-5);
    v.tijd = nu;
    v.sprongen = 0;
    vorige[sleutel] = v;
}
context.set("vorige", vorige);
stats.ok++;
context.set("stats", stats);
toonStatus();
return [msg, null];

// Berekent afgeleide waarden en zet ze in msg.payload.afgeleid.
// Gebruikt de laatste geldige temperatuur, vochtigheid en wind (in flow-context).
const laatste = flow.get("laatste") || {};
const d = msg.payload;

switch (msg.topic) {
    case "weer/temperatuur":      laatste.temp = d.waarde; break;
    case "weer/luchtvochtigheid": laatste.vocht = d.waarde; break;
    case "weer/wind":             laatste.wind = d.snelheid; break;
}
flow.set("laatste", laatste);

const r1 = x => Math.round(x * 10) / 10;

// Dauwpunt via de Magnus-formule
function dauwpunt(t, rh) {
    const a = 17.62, b = 243.12;
    const g = Math.log(rh / 100) + (a * t) / (b + t);
    return (b * g) / (a - g);
}
// Gevoelstemperatuur (windchill, JAG/TI-formule), enkel geldig bij <= 10 °C en wind > 4,8 km/h
function gevoelstemperatuur(t, v) {
    if (t > 10 || v <= 4.8) return t;
    return 13.12 + 0.6215 * t - 11.37 * Math.pow(v, 0.16) + 0.3965 * t * Math.pow(v, 0.16);
}
function kompas(graden) {
    const r = ["N", "NO", "O", "ZO", "Z", "ZW", "W", "NW"];
    return r[Math.round(graden / 45) % 8];
}
const BEAUFORT_GRENZEN = [1, 6, 12, 20, 29, 39, 50, 62, 75, 89, 103, 118]; // km/h
const BEAUFORT_NAAM = ["windstil", "zwak", "zwak", "matig", "matig", "vrij krachtig", "krachtig",
                       "hard", "stormachtig", "storm", "zware storm", "zeer zware storm", "orkaan"];
function beaufort(kmh) {
    let b = 0;
    while (b < BEAUFORT_GRENZEN.length && kmh >= BEAUFORT_GRENZEN[b]) b++;
    return b;
}
function regenIntensiteit(mm) {
    if (mm === 0) return "droog";
    if (mm < 2.5) return "licht";
    if (mm < 7.6) return "matig";
    return "zwaar";
}

const afgeleid = {};
switch (msg.topic) {
    case "weer/temperatuur":
        if (laatste.wind !== undefined) afgeleid.gevoelstemperatuur = r1(gevoelstemperatuur(d.waarde, laatste.wind));
        if (laatste.vocht !== undefined) afgeleid.dauwpunt = r1(dauwpunt(d.waarde, laatste.vocht));
        break;
    case "weer/luchtvochtigheid":
        if (laatste.temp !== undefined) afgeleid.dauwpunt = r1(dauwpunt(laatste.temp, d.waarde));
        break;
    case "weer/wind": {
        const bft = beaufort(d.snelheid);
        afgeleid.snelheid_ms = r1(d.snelheid / 3.6);
        afgeleid.windrichting = kompas(d.richting);
        afgeleid.beaufort = bft;
        afgeleid.beaufort_omschrijving = BEAUFORT_NAAM[bft];
        break;
    }
    case "weer/regen":
        afgeleid.intensiteit = regenIntensiteit(d.mm_per_uur);
        break;
}
d.afgeleid = afgeleid;
return msg;

// Stuurt een alarm op weer/alarm bij het begin ("actief") en einde ("voorbij") van
// storm, vorst of hevige regen. Hysterese voorkomt dat een alarm blijft aan/uit flikkeren.
const ALARMEN = [
    { type: "storm",        topic: "weer/wind",        veld: "snelheid",
      drempel: 60,  eenheid: "km/h", aan: v => v > 60,  uit: v => v < 55 },
    { type: "vorst",        topic: "weer/temperatuur", veld: "waarde",
      drempel: 0,   eenheid: "°C",   aan: v => v < 0,   uit: v => v >= 0.5 },
    { type: "hevige regen", topic: "weer/regen",       veld: "mm_per_uur",
      drempel: 7.6, eenheid: "mm/u", aan: v => v > 7.6, uit: v => v < 6 }
];

const actief = context.get("actief") || {};
const uit = [];
for (const a of ALARMEN) {
    if (a.topic !== msg.topic) continue;
    const w = msg.payload[a.veld];
    let status = null;
    if (!actief[a.type] && a.aan(w)) { actief[a.type] = true; status = "actief"; }
    else if (actief[a.type] && a.uit(w)) { actief[a.type] = false; status = "voorbij"; }
    if (status) {
        uit.push({ topic: "weer/alarm", payload: {
            type: a.type, status: status, waarde: w, drempel: a.drempel, eenheid: a.eenheid,
            station: msg.payload.station, ts: msg.payload.ts } });
    }
}
context.set("actief", actief);

const lijst = Object.keys(actief).filter(k => actief[k]);
node.status(lijst.length
    ? { fill: "red", shape: "dot", text: "actief: " + lijst.join(", ") }
    : { fill: "green", shape: "ring", text: "geen alarmen" });
return [uit];

// Zet een geldige meting (incl. afgeleide waarden) om naar InfluxDB line protocol.
// measurement = sensor (temperatuur, luchtvochtigheid, wind, regen), tag = station.
// --- InfluxDB line protocol + HTTP-schrijfverzoek (gegevens uit omgevingsvariabelen) ---
const esc = x => String(x).replace(/[,= ]/g, m => "\\" + m);
const veldwaarde = v => typeof v === "number"
    ? String(v) : '"' + String(v).replace(/["\\]/g, m => "\\" + m) + '"';
function lijn(measurement, tags, fields, ms) {
    const t = Object.entries(tags).map(([k, v]) => `,${esc(k)}=${esc(v)}`).join("");
    const f = Object.entries(fields).map(([k, v]) => `${esc(k)}=${veldwaarde(v)}`).join(",");
    return `${esc(measurement)}${t} ${f} ${ms}`;
}
function schrijfverzoek(msg, body) {
    msg.payload = body;
    msg.method = "POST";
    msg.url = env.get("INFLUXDB_URL") + "/api/v2/write?org=" + encodeURIComponent(env.get("INFLUXDB_ORG")) +
              "&bucket=" + encodeURIComponent(env.get("INFLUXDB_BUCKET")) + "&precision=ms";
    msg.headers = { "Authorization": "Token " + env.get("INFLUXDB_TOKEN"),
                    "Content-Type": "text/plain; charset=utf-8" };
    return msg;
}

const d = msg.payload;
const fields = {};
for (const [k, v] of Object.entries(d)) {
    if (typeof v === "number") fields[k] = v;
}
for (const [k, v] of Object.entries(d.afgeleid || {})) {
    if (typeof v === "number" || typeof v === "string") fields[k] = v;
}
const measurement = msg.topic.split("/")[1];
return schrijfverzoek(msg, lijn(measurement, { station: d.station }, fields, Date.parse(d.ts)));

// Zet een afgewezen meting om naar measurement "fouten" (tags: station, sensor, reden),
// zodat het dashboard het aantal fouten per sensor en per reden kan tonen.
// --- InfluxDB line protocol + HTTP-schrijfverzoek (gegevens uit omgevingsvariabelen) ---
const esc = x => String(x).replace(/[,= ]/g, m => "\\" + m);
const veldwaarde = v => typeof v === "number"
    ? String(v) : '"' + String(v).replace(/["\\]/g, m => "\\" + m) + '"';
function lijn(measurement, tags, fields, ms) {
    const t = Object.entries(tags).map(([k, v]) => `,${esc(k)}=${esc(v)}`).join("");
    const f = Object.entries(fields).map(([k, v]) => `${esc(k)}=${veldwaarde(v)}`).join(",");
    return `${esc(measurement)}${t} ${f} ${ms}`;
}
function schrijfverzoek(msg, body) {
    msg.payload = body;
    msg.method = "POST";
    msg.url = env.get("INFLUXDB_URL") + "/api/v2/write?org=" + encodeURIComponent(env.get("INFLUXDB_ORG")) +
              "&bucket=" + encodeURIComponent(env.get("INFLUXDB_BUCKET")) + "&precision=ms";
    msg.headers = { "Authorization": "Token " + env.get("INFLUXDB_TOKEN"),
                    "Content-Type": "text/plain; charset=utf-8" };
    return msg;
}

const f = msg.payload;
const ms = isNaN(Date.parse(f.ts)) ? Date.now() : Date.parse(f.ts);

// Tellers per reden, zichtbaar onder de node
const tel = context.get("tel") || {};
tel[f.reden] = (tel[f.reden] || 0) + 1;
context.set("tel", tel);
node.status({ fill: "yellow", shape: "ring",
              text: Object.entries(tel).map(([r, n]) => `${r}: ${n}`).join(" | ") });

const tags = { station: f.station, sensor: f.bron_topic.split("/")[1], reden: f.reden };
const fields = { aantal: 1, veld: f.veld || "-", waarde: JSON.stringify(f.waarde) };
return schrijfverzoek(msg, lijn("fouten", tags, fields, ms));

// Controleert het antwoord van InfluxDB (204 = gelukt) en toont een teller.
const tel = context.get("tel") || { ok: 0, fout: 0 };
if (msg.statusCode === 204) {
    tel.ok++;
} else {
    tel.fout++;
    const reden = msg.error ? (msg.error.message || msg.error) : `HTTP ${msg.statusCode}: ${msg.payload}`;
    node.warn("Schrijven naar InfluxDB mislukt: " + reden);
}
context.set("tel", tel);
node.status({ fill: tel.fout ? "red" : "green", shape: "dot",
              text: `geschreven ${tel.ok} | mislukt ${tel.fout}` });
return null;
